    await actual.evaluate(cv=>cv._issSetView('overview'));await page.waitForFunction(()=>!document.querySelector('#wrap .iss-station-stage canvas')._issCameraState().tweening);const before=await page.evaluate(()=>{window.__questSentinelCalls=[];const cv=document.querySelector('#wrap .iss-station-stage canvas');return{camera:cv._issCameraState(),data:structuredClone(window.__toolData),xp:window.__questXP.slice()};});
    await activate(page.locator('#wrap '+selector));await page.waitForFunction(()=>!document.querySelector('#wrap .iss-station-stage canvas')._issCameraState().tweening);await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));
